begin;

create type academic.student_record_status as enum ('DRAFT','ACTIVE','TEMPORARILY_WITHDRAWN','ACADEMICALLY_BLOCKED','COMPLETED','GRADUATED','PERMANENTLY_WITHDRAWN','CANCELLED');
create type academic.student_generation_status as enum ('DRAFT','ACTIVE','CLOSED','CANCELLED');
create type academic.enrollment_request_type as enum ('INITIAL_ENROLLMENT','REENROLLMENT','REPEAT_SEMESTER','REENTRY_AFTER_TEMPORARY_WITHDRAWAL');
create type academic.enrollment_request_status as enum ('DRAFT','SUBMITTED','UNDER_REVIEW','APPROVED','REJECTED','ENROLLED','CANCELLED','EXPIRED');
create type academic.enrollment_eligibility_status as enum ('PENDING_EVALUATION','ELIGIBLE','ELIGIBLE_WITH_CONDITIONS','NOT_ELIGIBLE','MANUAL_REVIEW_REQUIRED');
create type academic.enrollment_eligibility_reason as enum ('INITIAL_ENROLLMENT_ALLOWED','PREVIOUS_PERIOD_APPROVED','REPEAT_REQUIRED','ACADEMIC_RESULT_PENDING','ACCOUNT_NOT_ACTIVE','STUDENT_RECORD_NOT_ACTIVE','PERIOD_NOT_AVAILABLE','PLAN_NOT_COMPATIBLE','SEMESTER_NOT_ALLOWED','AREA_REQUIRED','AREA_NOT_ALLOWED','GROUP_NOT_COMPATIBLE','GROUP_CAPACITY_REACHED','ACTIVE_ENROLLMENT_EXISTS','TEMPORARY_WITHDRAWAL_REVIEW','ADMINISTRATIVE_HOLD','INSTITUTIONAL_VALIDATION_PENDING');
create type academic.progress_decision_type as enum ('ADVANCE','REPEAT','HOLD','TEMPORARY_WITHDRAWAL','PERMANENT_WITHDRAWAL','COMPLETE_STUDIES');
create type academic.progress_decision_status as enum ('DRAFT','CONFIRMED','REVERSED','CANCELLED');
create type academic.period_enrollment_status as enum ('PLANNED','ACTIVE','TEMPORARILY_SUSPENDED','COMPLETED','CANCELLED','WITHDRAWN');
create type academic.student_group_assignment_type as enum ('INITIAL','ADMINISTRATIVE_CHANGE','CORRECTIVE_CHANGE');
create type academic.student_group_assignment_status as enum ('ACTIVE','ENDED','CANCELLED');
create type academic.student_offering_enrollment_status as enum ('ACTIVE','COMPLETED','CANCELLED');
create type academic.student_offering_enrollment_source as enum ('GROUP_CURRICULUM','ADMINISTRATIVE_CORRECTION');
create type academic.student_history_reason as enum ('INITIAL_ENROLLMENT','INSTITUTIONAL_ACTIVATION','ACADEMIC_DECISION','REPEAT_REQUIRED','ADMINISTRATIVE_HOLD','HOLD_RELEASED','TEMPORARY_WITHDRAWAL','REACTIVATION','PERMANENT_WITHDRAWAL','STUDIES_COMPLETED','GRADUATION_CONFIRMED','CORRECTIVE_ACTION');
create type academic.student_source_entity_type as enum ('STUDENT_RECORD','GENERATION','ENROLLMENT_REQUEST','PERIOD_ENROLLMENT','GROUP_ASSIGNMENT','OFFERING_ENROLLMENT','PROGRESS_DECISION');
create type academic.student_academic_event_type as enum ('STUDENT_RECORD_CREATED','STUDENT_RECORD_ACTIVATED','GENERATION_CREATED','GENERATION_ACTIVATED','GENERATION_CLOSED','ENROLLMENT_REQUEST_CREATED','ENROLLMENT_REQUEST_SUBMITTED','ENROLLMENT_REQUEST_REVIEW_STARTED','ENROLLMENT_REQUEST_APPROVED','ENROLLMENT_REQUEST_REJECTED','ENROLLMENT_REQUEST_CANCELLED','ENROLLMENT_REQUEST_EXPIRED','PERIOD_ENROLLMENT_CREATED','PERIOD_ENROLLMENT_ACTIVATED','PERIOD_ENROLLMENT_COMPLETED','PERIOD_ENROLLMENT_CANCELLED','PERIOD_ENROLLMENT_WITHDRAWN','GROUP_ASSIGNED','GROUP_ASSIGNMENT_ENDED','GROUP_CHANGED','OFFERING_ENROLLMENTS_CREATED','OFFERING_ENROLLMENT_CANCELLED','PROGRESS_DECISION_CREATED','PROGRESS_DECISION_CONFIRMED','PROGRESS_DECISION_REVERSED','SEMESTER_ADVANCED','SEMESTER_REPEAT_REQUIRED','ACADEMIC_HOLD_APPLIED','ACADEMIC_HOLD_RELEASED','TEMPORARY_WITHDRAWAL_APPLIED','STUDENT_REACTIVATED','PERMANENT_WITHDRAWAL_APPLIED','STUDIES_COMPLETED','OPERATION_REJECTED');
create type academic.enrollment_command_status as enum ('IN_PROGRESS','COMPLETED','FAILED');
create type academic.enrollment_command_type as enum ('CREATE_STUDENT_GENERATION','ACTIVATE_STUDENT_GENERATION','CLOSE_STUDENT_GENERATION','CREATE_STUDENT_RECORD','ACTIVATE_STUDENT_RECORD','CREATE_ENROLLMENT_REQUEST','SUBMIT_ENROLLMENT_REQUEST','BEGIN_ENROLLMENT_REVIEW','APPROVE_ENROLLMENT_REQUEST','REJECT_ENROLLMENT_REQUEST','CANCEL_ENROLLMENT_REQUEST','EXPIRE_ENROLLMENT_REQUEST','CREATE_PROGRESS_DECISION','CONFIRM_PROGRESS_DECISION','REVERSE_PROGRESS_DECISION','CREATE_PERIOD_ENROLLMENT','ACTIVATE_PERIOD_ENROLLMENT','COMPLETE_PERIOD_ENROLLMENT','CANCEL_PERIOD_ENROLLMENT','WITHDRAW_PERIOD_ENROLLMENT','ASSIGN_STUDENT_GROUP','CHANGE_STUDENT_GROUP','END_STUDENT_GROUP_ASSIGNMENT','ENROLL_STUDENT_IN_GROUP_OFFERINGS','APPLY_TEMPORARY_WITHDRAWAL','REACTIVATE_STUDENT_RECORD','APPLY_ACADEMIC_HOLD','RELEASE_ACADEMIC_HOLD','APPLY_PERMANENT_WITHDRAWAL','COMPLETE_STUDENT_STUDIES');

create table academic.student_generations (
 id uuid primary key default gen_random_uuid(), code academic.normalized_code not null unique, name text not null check(char_length(btrim(name)) between 2 and 120),
 entry_school_cycle_id uuid not null references academic.school_cycles(id) on delete restrict, expected_completion_cycle_id uuid references academic.school_cycles(id) on delete restrict,
 study_plan_id uuid not null references academic.study_plans(id) on delete restrict, status academic.student_generation_status not null default 'DRAFT',
 created_by_account_id uuid not null references core.accounts(id) on delete restrict, created_at timestamptz not null default now(), closed_at timestamptz, updated_at timestamptz not null default now()
);
create table academic.student_records (
 id uuid primary key default gen_random_uuid(), person_id uuid not null references core.people(id) on delete restrict, account_id uuid not null references core.accounts(id) on delete restrict,
 study_plan_id uuid not null references academic.study_plans(id) on delete restrict, generation_id uuid not null references academic.student_generations(id) on delete restrict,
 institutional_student_code text, status academic.student_record_status not null default 'DRAFT', current_semester_number smallint check(current_semester_number between 1 and 6),
 current_training_area_id uuid references academic.training_areas(id) on delete restrict, first_enrollment_period_id uuid references academic.academic_periods(id) on delete restrict,
 last_enrollment_period_id uuid references academic.academic_periods(id) on delete restrict, created_by_account_id uuid not null references core.accounts(id) on delete restrict,
 created_at timestamptz not null default now(), activated_at timestamptz, graduated_at timestamptz, withdrawn_at timestamptz, updated_at timestamptz not null default now(),
 unique(account_id), unique(institutional_student_code), check(institutional_student_code is null or char_length(institutional_student_code) between 1 and 40),
 check((current_semester_number is null) or (current_semester_number<5 and current_training_area_id is null) or current_semester_number>=5)
);
create unique index one_active_student_record_per_person on academic.student_records(person_id) where status not in ('CANCELLED','PERMANENTLY_WITHDRAWN');

create table academic.enrollment_requests (
 id uuid primary key default gen_random_uuid(), student_record_id uuid not null references academic.student_records(id) on delete restrict,
 academic_period_id uuid not null references academic.academic_periods(id) on delete restrict, request_type academic.enrollment_request_type not null,
 requested_semester_number smallint not null check(requested_semester_number between 1 and 6), requested_training_area_id uuid references academic.training_areas(id) on delete restrict,
 requested_group_id uuid references academic.groups(id) on delete restrict, status academic.enrollment_request_status not null default 'DRAFT',
 eligibility_status academic.enrollment_eligibility_status not null default 'PENDING_EVALUATION', eligibility_reason_code academic.enrollment_eligibility_reason,
 requested_by_account_id uuid not null references core.accounts(id) on delete restrict, reviewed_by_account_id uuid references core.accounts(id) on delete restrict,
 approved_by_account_id uuid references core.accounts(id) on delete restrict, rejected_by_account_id uuid references core.accounts(id) on delete restrict,
 idempotency_key academic.normalized_code not null, request_fingerprint text not null check(request_fingerprint~'^[0-9a-f]{64}$'),
 requested_at timestamptz not null default now(), reviewed_at timestamptz, approved_at timestamptz, rejected_at timestamptz, cancelled_at timestamptz, expires_at timestamptz,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(requested_by_account_id,idempotency_key),
 check((requested_semester_number<5 and requested_training_area_id is null) or requested_semester_number>=5)
);

create table academic.period_enrollments (
 id uuid primary key default gen_random_uuid(), student_record_id uuid not null references academic.student_records(id) on delete restrict,
 enrollment_request_id uuid not null unique references academic.enrollment_requests(id) on delete restrict, academic_period_id uuid not null references academic.academic_periods(id) on delete restrict,
 study_plan_id uuid not null references academic.study_plans(id) on delete restrict, semester_number smallint not null check(semester_number between 1 and 6),
 training_area_id uuid references academic.training_areas(id) on delete restrict, group_id uuid not null references academic.groups(id) on delete restrict,
 status academic.period_enrollment_status not null default 'PLANNED', enrollment_number text, enrolled_by_account_id uuid not null references core.accounts(id) on delete restrict,
 cancelled_by_account_id uuid references core.accounts(id) on delete restrict, completed_by_account_id uuid references core.accounts(id) on delete restrict,
 enrolled_at timestamptz not null default now(), cancelled_at timestamptz, completed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 check(enrollment_number is null or char_length(enrollment_number) between 1 and 40), check((semester_number<5 and training_area_id is null) or semester_number>=5)
);
create unique index one_operational_enrollment_per_period on academic.period_enrollments(student_record_id,academic_period_id) where status in ('PLANNED','ACTIVE','TEMPORARILY_SUSPENDED');

create table academic.student_group_assignments (
 id uuid primary key default gen_random_uuid(), period_enrollment_id uuid not null references academic.period_enrollments(id) on delete restrict,
 group_id uuid not null references academic.groups(id) on delete restrict, assignment_type academic.student_group_assignment_type not null,
 status academic.student_group_assignment_status not null default 'ACTIVE', assigned_by_account_id uuid not null references core.accounts(id) on delete restrict,
 ended_by_account_id uuid references core.accounts(id) on delete restrict, valid_from timestamptz not null default now(), valid_to timestamptz,
 reason_code academic.student_history_reason not null, idempotency_key academic.normalized_code not null unique, created_at timestamptz not null default now(), ended_at timestamptz,
 check(valid_to is null or valid_to>=valid_from)
);
create unique index one_active_group_assignment on academic.student_group_assignments(period_enrollment_id) where status='ACTIVE';

create table academic.student_offering_enrollments (
 id uuid primary key default gen_random_uuid(), period_enrollment_id uuid not null references academic.period_enrollments(id) on delete restrict,
 academic_offering_id uuid not null references academic.academic_offerings(id) on delete restrict, status academic.student_offering_enrollment_status not null default 'ACTIVE',
 enrollment_source academic.student_offering_enrollment_source not null default 'GROUP_CURRICULUM', enrolled_by_account_id uuid not null references core.accounts(id) on delete restrict,
 enrolled_at timestamptz not null default now(), cancelled_at timestamptz, completed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 unique(period_enrollment_id,academic_offering_id)
);

create table academic.academic_progress_decisions (
 id uuid primary key default gen_random_uuid(), student_record_id uuid not null references academic.student_records(id) on delete restrict,
 source_period_enrollment_id uuid references academic.period_enrollments(id) on delete restrict, source_academic_period_id uuid not null references academic.academic_periods(id) on delete restrict,
 decision_type academic.progress_decision_type not null, resulting_semester_number smallint not null check(resulting_semester_number between 1 and 6),
 resulting_training_area_id uuid references academic.training_areas(id) on delete restrict, decision_status academic.progress_decision_status not null default 'DRAFT',
 reason_code academic.enrollment_eligibility_reason not null, decided_by_account_id uuid not null references core.accounts(id) on delete restrict,
 approved_by_account_id uuid references core.accounts(id) on delete restrict, idempotency_key academic.normalized_code not null unique,
 request_fingerprint text not null check(request_fingerprint~'^[0-9a-f]{64}$'), effective_from_period_id uuid references academic.academic_periods(id) on delete restrict,
 decided_at timestamptz not null default now(), reversed_at timestamptz, created_at timestamptz not null default now(),
 check((resulting_semester_number<5 and resulting_training_area_id is null) or resulting_semester_number>=5)
);
create unique index one_confirmed_progress_decision on academic.academic_progress_decisions(student_record_id,source_academic_period_id) where decision_status='CONFIRMED';

create table academic.student_status_history (
 id uuid primary key default gen_random_uuid(), student_record_id uuid not null references academic.student_records(id) on delete restrict,
 previous_status academic.student_record_status, resulting_status academic.student_record_status not null, reason_code academic.student_history_reason not null,
 actor_account_id uuid not null references core.accounts(id) on delete restrict, source_entity_type academic.student_source_entity_type,
 source_entity_id uuid, effective_at timestamptz not null default now(), created_at timestamptz not null default now()
);
create table academic.enrollment_commands (
 id uuid primary key default gen_random_uuid(), idempotency_key academic.normalized_code not null, command_type academic.enrollment_command_type not null,
 actor_account_id uuid not null references core.accounts(id) on delete restrict, request_fingerprint text not null check(request_fingerprint~'^[0-9a-f]{64}$'),
 resulting_entity_type academic.student_source_entity_type, resulting_entity_id uuid, status academic.enrollment_command_status not null default 'IN_PROGRESS',
 created_at timestamptz not null default now(), completed_at timestamptz, unique(actor_account_id,command_type,idempotency_key),
 check((status='COMPLETED')=(completed_at is not null))
);
create table academic.student_academic_events (
 id uuid primary key default gen_random_uuid(), student_record_id uuid not null references academic.student_records(id) on delete restrict,
 entity_type academic.student_source_entity_type not null, entity_id uuid not null, event_type academic.student_academic_event_type not null,
 actor_account_id uuid not null references core.accounts(id) on delete restrict, previous_status text, resulting_status text,
 reason_code academic.student_history_reason not null, idempotency_key academic.normalized_code not null unique, correlation_id uuid, occurred_at timestamptz not null default now()
);

create index student_records_person_idx on academic.student_records(person_id,status);
create index student_records_generation_idx on academic.student_records(generation_id,status);
create index enrollment_requests_record_period_idx on academic.enrollment_requests(student_record_id,academic_period_id,status);
create index period_enrollments_group_status_idx on academic.period_enrollments(group_id,status);
create index group_assignments_group_status_idx on academic.student_group_assignments(group_id,status);
create index offering_enrollments_period_idx on academic.student_offering_enrollments(period_enrollment_id,status);
create index progress_decisions_record_idx on academic.academic_progress_decisions(student_record_id,source_academic_period_id,decision_status);
create index status_history_record_idx on academic.student_status_history(student_record_id,effective_at desc);
create index enrollment_events_record_idx on academic.student_academic_events(student_record_id,occurred_at desc);
create index enrollment_commands_created_idx on academic.enrollment_commands(created_at);

do $$declare table_name text; begin foreach table_name in array array['student_generations','student_records','enrollment_requests','period_enrollments','student_group_assignments','student_offering_enrollments','academic_progress_decisions','student_status_history','enrollment_commands','student_academic_events'] loop execute format('alter table academic.%I enable row level security',table_name); execute format('revoke all on table academic.%I from public,anon,authenticated',table_name); end loop; end$$;

create function academic.require_student_enrollment_permission(permission_code text)
returns uuid language plpgsql stable security definer set search_path='' as $$declare actor core.accounts%rowtype; role_codes text[];
begin
 if permission_code not in ('academic.students.read','academic.students.manage','academic.generations.read','academic.generations.manage','academic.enrollment_requests.read','academic.enrollment_requests.manage','academic.enrollments.read','academic.enrollments.manage','academic.group_assignments.read','academic.group_assignments.manage','academic.progress.read','academic.progress.manage','academic.withdrawals.manage') then raise exception using errcode='42501',message='ACTOR_NOT_AUTHORIZED'; end if;
 if auth.uid() is null then raise exception using errcode='42501',message='ACTOR_NOT_AUTHORIZED'; end if;
 select * into actor from core.accounts where auth_user_id=auth.uid();
 if actor.id is null or actor.account_status<>'ACTIVE' then raise exception using errcode='42501',message='ACTOR_NOT_AUTHORIZED'; end if;
 if not core.is_current_session_version_valid() then raise exception using errcode='42501',message='SESSION_VERSION_INVALID'; end if;
 if not core.is_current_aal2() or not core.is_current_mfa_policy_satisfied() then raise exception using errcode='42501',message='AAL2_REQUIRED'; end if;
 select coalesce(array_agg(r.code),array[]::text[]) into role_codes from core.account_roles ar join core.roles r on r.id=ar.role_id and r.is_active where ar.account_id=actor.id and ar.revoked_at is null;
 if not (role_codes&&array['SUPERADMIN','ADMINISTRATIVO','CONTROL_ESCOLAR']) then raise exception using errcode='42501',message='ACTOR_NOT_AUTHORIZED'; end if;
 if role_codes&&array['CONTROL_ESCOLAR'] and not (role_codes&&array['SUPERADMIN','ADMINISTRATIVO']) and permission_code='academic.withdrawals.manage' then raise exception using errcode='42501',message='ACTOR_NOT_AUTHORIZED'; end if;
 return actor.id;
end$$;

create function academic.begin_enrollment_command(actor_id uuid,command_name academic.enrollment_command_type,operation_key text,payload jsonb)
returns uuid language plpgsql security definer set search_path='' as $$declare existing academic.enrollment_commands%rowtype; fingerprint text:=academic.academic_request_fingerprint(payload);
begin
 select * into existing from academic.enrollment_commands where actor_account_id=actor_id and command_type=command_name and idempotency_key=operation_key for update;
 if existing.id is not null then if existing.request_fingerprint<>fingerprint then raise exception 'IDEMPOTENCY_CONFLICT'; end if; return existing.resulting_entity_id; end if;
 begin insert into academic.enrollment_commands(idempotency_key,command_type,actor_account_id,request_fingerprint) values(operation_key,command_name,actor_id,fingerprint);
 exception when unique_violation then select * into existing from academic.enrollment_commands where actor_account_id=actor_id and command_type=command_name and idempotency_key=operation_key for update; if existing.request_fingerprint<>fingerprint then raise exception 'IDEMPOTENCY_CONFLICT'; end if; return existing.resulting_entity_id; end;
 return null;
end$$;
create function academic.complete_enrollment_command(actor_id uuid,command_name academic.enrollment_command_type,operation_key text,entity_type academic.student_source_entity_type,entity_id uuid)
returns void language sql security definer set search_path='' as $$update academic.enrollment_commands set status='COMPLETED',resulting_entity_type=entity_type,resulting_entity_id=entity_id,completed_at=statement_timestamp() where actor_account_id=actor_id and command_type=command_name and idempotency_key=operation_key$$;
create function academic.append_student_event(record_id uuid,entity_type academic.student_source_entity_type,entity_id uuid,event_type academic.student_academic_event_type,actor_id uuid,previous_status text,resulting_status text,reason academic.student_history_reason,operation_key text,correlation uuid)
returns void language sql security definer set search_path='' as $$insert into academic.student_academic_events(student_record_id,entity_type,entity_id,event_type,actor_account_id,previous_status,resulting_status,reason_code,idempotency_key,correlation_id) values(record_id,entity_type,entity_id,event_type,actor_id,previous_status,resulting_status,reason,operation_key,correlation)$$;

create function academic.valid_student_record_transition(old_status academic.student_record_status,new_status academic.student_record_status) returns boolean language sql immutable security invoker set search_path='' as $$select (old_status,new_status) in (('DRAFT','ACTIVE'),('ACTIVE','TEMPORARILY_WITHDRAWN'),('TEMPORARILY_WITHDRAWN','ACTIVE'),('ACTIVE','ACADEMICALLY_BLOCKED'),('ACADEMICALLY_BLOCKED','ACTIVE'),('ACTIVE','COMPLETED'),('COMPLETED','GRADUATED'),('ACTIVE','PERMANENTLY_WITHDRAWN'),('DRAFT','CANCELLED'))$$;
create function academic.valid_enrollment_request_transition(old_status academic.enrollment_request_status,new_status academic.enrollment_request_status) returns boolean language sql immutable security invoker set search_path='' as $$select (old_status,new_status) in (('DRAFT','SUBMITTED'),('SUBMITTED','UNDER_REVIEW'),('UNDER_REVIEW','APPROVED'),('UNDER_REVIEW','REJECTED'),('APPROVED','ENROLLED'),('DRAFT','CANCELLED'),('SUBMITTED','CANCELLED'),('APPROVED','CANCELLED'),('SUBMITTED','EXPIRED'),('UNDER_REVIEW','EXPIRED'))$$;
create function academic.valid_period_enrollment_transition(old_status academic.period_enrollment_status,new_status academic.period_enrollment_status) returns boolean language sql immutable security invoker set search_path='' as $$select (old_status,new_status) in (('PLANNED','ACTIVE'),('ACTIVE','TEMPORARILY_SUSPENDED'),('TEMPORARILY_SUSPENDED','ACTIVE'),('ACTIVE','COMPLETED'),('PLANNED','CANCELLED'),('ACTIVE','CANCELLED'),('ACTIVE','WITHDRAWN'))$$;
create function academic.valid_progress_decision_transition(old_status academic.progress_decision_status,new_status academic.progress_decision_status) returns boolean language sql immutable security invoker set search_path='' as $$select (old_status,new_status) in (('DRAFT','CONFIRMED'),('DRAFT','CANCELLED'),('CONFIRMED','REVERSED'))$$;

create function academic.guard_student_academic_history() returns trigger language plpgsql security invoker set search_path='' as $$begin
 if current_setting('academic.student_controlled_mutation',true)='on' then return new; end if;
 if tg_op='DELETE' then raise exception 'HISTORICAL_RECORD_IMMUTABLE'; end if;
 if tg_table_name in ('student_status_history','student_academic_events') then raise exception 'HISTORICAL_RECORD_IMMUTABLE'; end if;
 if tg_table_name='enrollment_commands' then if old.status='COMPLETED' and new is distinct from old then raise exception 'HISTORICAL_RECORD_IMMUTABLE'; end if; end if;
 if tg_table_name='student_records' then if old.status in ('COMPLETED','GRADUATED','PERMANENTLY_WITHDRAWN') and new is distinct from old then raise exception 'HISTORICAL_RECORD_IMMUTABLE'; end if; if old.status<>'DRAFT' and (new.person_id,new.account_id,new.study_plan_id,new.generation_id) is distinct from (old.person_id,old.account_id,old.study_plan_id,old.generation_id) then raise exception 'HISTORICAL_RECORD_IMMUTABLE'; end if; end if;
 if tg_table_name='enrollment_requests' then if old.status in ('ENROLLED','REJECTED','EXPIRED','CANCELLED') and new is distinct from old then raise exception 'HISTORICAL_RECORD_IMMUTABLE'; end if; end if;
 if tg_table_name='period_enrollments' then if old.status in ('COMPLETED','CANCELLED','WITHDRAWN') and new is distinct from old then raise exception 'HISTORICAL_RECORD_IMMUTABLE'; end if; if old.status<>'PLANNED' and (new.student_record_id,new.academic_period_id,new.study_plan_id,new.semester_number,new.training_area_id,new.group_id) is distinct from (old.student_record_id,old.academic_period_id,old.study_plan_id,old.semester_number,old.training_area_id,old.group_id) then raise exception 'HISTORICAL_RECORD_IMMUTABLE'; end if; end if;
 if tg_table_name='student_group_assignments' then if old.status='ENDED' and new is distinct from old then raise exception 'HISTORICAL_RECORD_IMMUTABLE'; end if; end if;
 if tg_table_name='academic_progress_decisions' then if old.decision_status in ('CONFIRMED','REVERSED') and new is distinct from old then raise exception 'HISTORICAL_RECORD_IMMUTABLE'; end if; end if;
 return new;
end$$;
do $$declare table_name text; begin foreach table_name in array array['student_generations','student_records','enrollment_requests','period_enrollments','student_group_assignments','student_offering_enrollments','academic_progress_decisions','student_status_history','enrollment_commands','student_academic_events'] loop execute format('create trigger %I_history before update or delete on academic.%I for each row execute function academic.guard_student_academic_history()',table_name,table_name); end loop; end$$;

create function academic.create_student_generation(generation_code text,generation_name text,entry_cycle uuid,completion_cycle uuid,plan_id uuid,operation_key text,correlation uuid default null)
returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; created uuid; entry_start date; completion_start date; plan_status academic.study_plan_status;
begin actor:=academic.require_student_enrollment_permission('academic.generations.manage'); prior:=academic.begin_enrollment_command(actor,'CREATE_STUDENT_GENERATION',operation_key,jsonb_build_object('code',upper(btrim(generation_code)),'name',btrim(generation_name),'entry',entry_cycle,'completion',completion_cycle,'plan',plan_id)); if prior is not null then return query select prior,'DRAFT'; return; end if;
 select starts_on into entry_start from academic.school_cycles where id=entry_cycle; select starts_on into completion_start from academic.school_cycles where id=completion_cycle; select p.status into plan_status from academic.study_plans p where p.id=plan_id;
 if entry_start is null or (completion_cycle is not null and (completion_start is null or completion_start<=entry_start)) then raise exception 'GENERATION_NOT_FOUND'; end if; if plan_status not in ('APPROVED','ACTIVE') then raise exception 'STUDY_PLAN_NOT_COMPATIBLE'; end if;
 insert into academic.student_generations(code,name,entry_school_cycle_id,expected_completion_cycle_id,study_plan_id,created_by_account_id) values(upper(btrim(generation_code)),btrim(generation_name),entry_cycle,completion_cycle,plan_id,actor) returning id into created;
 perform academic.complete_enrollment_command(actor,'CREATE_STUDENT_GENERATION',operation_key,'GENERATION',created); return query select created,'DRAFT'; end$$;

create function academic.change_student_generation_status(generation_id uuid,target academic.student_generation_status,command_name academic.enrollment_command_type,operation_key text,correlation uuid)
returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; current academic.student_generation_status;
begin actor:=academic.require_student_enrollment_permission('academic.generations.manage'); prior:=academic.begin_enrollment_command(actor,command_name,operation_key,jsonb_build_object('generation',generation_id,'target',target)); if prior is not null then return query select prior,target::text; return; end if; select g.status into current from academic.student_generations g where g.id=generation_id for update;
 if current is null or not ((current,target) in (('DRAFT','ACTIVE'),('ACTIVE','CLOSED'))) then raise exception 'INVALID_STATE_TRANSITION'; end if; perform set_config('academic.student_controlled_mutation','on',true); update academic.student_generations set status=target,closed_at=case when target='CLOSED' then statement_timestamp() else closed_at end,updated_at=statement_timestamp() where id=generation_id; perform set_config('academic.student_controlled_mutation','off',true); perform academic.complete_enrollment_command(actor,command_name,operation_key,'GENERATION',generation_id); return query select generation_id,target::text; end$$;
create function academic.activate_student_generation(generation_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_student_generation_status(generation_id,'ACTIVE','ACTIVATE_STUDENT_GENERATION',operation_key,correlation)$$;
create function academic.close_student_generation(generation_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_student_generation_status(generation_id,'CLOSED','CLOSE_STUDENT_GENERATION',operation_key,correlation)$$;

create function academic.create_student_record(person_id uuid,account_id uuid,plan_id uuid,generation_id uuid,student_code text,semester smallint,area_id uuid,operation_key text,correlation uuid default null)
returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; created uuid; generation academic.student_generations%rowtype;
begin actor:=academic.require_student_enrollment_permission('academic.students.manage'); prior:=academic.begin_enrollment_command(actor,'CREATE_STUDENT_RECORD',operation_key,jsonb_build_object('person',person_id,'account',account_id,'plan',plan_id,'generation',generation_id,'code',student_code,'semester',semester,'area',area_id)); if prior is not null then return query select prior,'DRAFT'; return; end if;
 if not exists(select 1 from core.accounts a where a.id=$2 and a.person_id=$1 and a.account_status in ('PENDING_ACTIVATION','ACTIVE')) then raise exception 'STUDENT_PERSON_ACCOUNT_MISMATCH'; end if;
 if not exists(select 1 from core.account_roles ar join core.roles r on r.id=ar.role_id and r.code='ALUMNO' and r.is_active where ar.account_id=$2 and ar.revoked_at is null) then raise exception 'STUDENT_ROLE_REQUIRED'; end if;
 select * into generation from academic.student_generations g where g.id=$4; if generation.id is null then raise exception 'GENERATION_NOT_FOUND'; end if; if generation.study_plan_id<>$3 then raise exception 'STUDY_PLAN_NOT_COMPATIBLE'; end if;
 if $6 not between 1 and 6 or ($6<5 and $7 is not null) or ($6>=5 and ($7 is null or not exists(select 1 from academic.training_areas a where a.id=$7 and a.status='ACTIVE'))) then raise exception 'TRAINING_AREA_NOT_ALLOWED'; end if;
 insert into academic.student_records(person_id,account_id,study_plan_id,generation_id,institutional_student_code,current_semester_number,current_training_area_id,created_by_account_id) values($1,$2,$3,$4,$5,$6,$7,actor) returning id into created;
 insert into academic.student_status_history(student_record_id,resulting_status,reason_code,actor_account_id,source_entity_type,source_entity_id) values(created,'DRAFT','INITIAL_ENROLLMENT',actor,'STUDENT_RECORD',created);
 perform academic.append_student_event(created,'STUDENT_RECORD',created,'STUDENT_RECORD_CREATED',actor,null,'DRAFT','INITIAL_ENROLLMENT',operation_key,correlation); perform academic.complete_enrollment_command(actor,'CREATE_STUDENT_RECORD',operation_key,'STUDENT_RECORD',created); return query select created,'DRAFT'; end$$;

create function academic.activate_student_record(record_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; record academic.student_records%rowtype;
begin actor:=academic.require_student_enrollment_permission('academic.students.manage'); prior:=academic.begin_enrollment_command(actor,'ACTIVATE_STUDENT_RECORD',operation_key,jsonb_build_object('record',record_id)); if prior is not null then return query select prior,'ACTIVE'; return; end if; select * into record from academic.student_records where id=record_id for update;
 if record.id is null then raise exception 'STUDENT_RECORD_NOT_FOUND'; end if; if record.status<>'DRAFT' then raise exception 'INVALID_STATE_TRANSITION'; end if; if not exists(select 1 from core.accounts a where a.id=record.account_id and a.account_status='ACTIVE') then raise exception 'STUDENT_ACCOUNT_NOT_ACTIVE'; end if; if not exists(select 1 from academic.student_generations g where g.id=record.generation_id and g.status='ACTIVE') then raise exception 'GENERATION_NOT_ACTIVE'; end if; if not exists(select 1 from academic.study_plans p where p.id=record.study_plan_id and p.status in ('APPROVED','ACTIVE')) then raise exception 'STUDY_PLAN_NOT_COMPATIBLE'; end if;
 perform set_config('academic.student_controlled_mutation','on',true); update academic.student_records set status='ACTIVE',activated_at=statement_timestamp(),updated_at=statement_timestamp() where id=record_id; perform set_config('academic.student_controlled_mutation','off',true);
 insert into academic.student_status_history(student_record_id,previous_status,resulting_status,reason_code,actor_account_id,source_entity_type,source_entity_id) values(record_id,'DRAFT','ACTIVE','INSTITUTIONAL_ACTIVATION',actor,'STUDENT_RECORD',record_id);
 perform academic.append_student_event(record_id,'STUDENT_RECORD',record_id,'STUDENT_RECORD_ACTIVATED',actor,'DRAFT','ACTIVE','INSTITUTIONAL_ACTIVATION',operation_key,correlation); perform academic.complete_enrollment_command(actor,'ACTIVATE_STUDENT_RECORD',operation_key,'STUDENT_RECORD',record_id); return query select record_id,'ACTIVE'; end$$;

create function academic.create_enrollment_request(record_id uuid,period_id uuid,kind academic.enrollment_request_type,semester smallint,area_id uuid,group_id uuid,eligibility academic.enrollment_eligibility_status,reason academic.enrollment_eligibility_reason,operation_key text,correlation uuid default null)
returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; created uuid; record academic.student_records%rowtype; period_status academic.structure_status; g academic.groups%rowtype;
begin actor:=academic.require_student_enrollment_permission('academic.enrollment_requests.manage'); prior:=academic.begin_enrollment_command(actor,'CREATE_ENROLLMENT_REQUEST',operation_key,jsonb_build_object('record',record_id,'period',period_id,'kind',kind,'semester',semester,'area',area_id,'group',group_id,'eligibility',eligibility,'reason',reason)); if prior is not null then return query select prior,'DRAFT'; return; end if;
 select * into record from academic.student_records where id=record_id for update; if record.id is null then raise exception 'STUDENT_RECORD_NOT_FOUND'; end if; if record.status<>'ACTIVE' and not (kind='REENTRY_AFTER_TEMPORARY_WITHDRAWAL' and record.status='TEMPORARILY_WITHDRAWN') then raise exception 'STUDENT_RECORD_NOT_ACTIVE'; end if;
 select p.status into period_status from academic.academic_periods p where p.id=period_id; if period_status not in ('PLANNED','ACTIVE') then raise exception 'PERIOD_NOT_AVAILABLE'; end if; if semester not between 1 and 6 or (semester<5 and area_id is not null) or (semester>=5 and area_id is null) then raise exception 'SEMESTER_NOT_ALLOWED'; end if;
 if group_id is not null then select * into g from academic.groups where id=group_id; if g.id is null or g.academic_period_id<>period_id or g.study_plan_id<>record.study_plan_id or g.semester_number<>semester or g.training_area_id is distinct from area_id then raise exception 'GROUP_NOT_COMPATIBLE'; end if; end if;
 if kind<>'INITIAL_ENROLLMENT' and eligibility='ELIGIBLE' and not exists(select 1 from academic.academic_progress_decisions d where d.student_record_id=record_id and d.decision_status='CONFIRMED' and d.effective_from_period_id=period_id and d.resulting_semester_number=semester and d.resulting_training_area_id is not distinct from area_id) then raise exception 'PROGRESS_DECISION_REQUIRED'; end if;
 insert into academic.enrollment_requests(student_record_id,academic_period_id,request_type,requested_semester_number,requested_training_area_id,requested_group_id,eligibility_status,eligibility_reason_code,requested_by_account_id,idempotency_key,request_fingerprint) values(record_id,period_id,kind,semester,area_id,group_id,eligibility,reason,actor,operation_key,academic.academic_request_fingerprint(jsonb_build_object('record',record_id,'period',period_id,'kind',kind,'semester',semester,'area',area_id,'group',group_id,'eligibility',eligibility,'reason',reason))) returning id into created;
 perform academic.append_student_event(record_id,'ENROLLMENT_REQUEST',created,'ENROLLMENT_REQUEST_CREATED',actor,null,'DRAFT','INITIAL_ENROLLMENT',operation_key,correlation); perform academic.complete_enrollment_command(actor,'CREATE_ENROLLMENT_REQUEST',operation_key,'ENROLLMENT_REQUEST',created); return query select created,'DRAFT'; end$$;

create function academic.change_enrollment_request_status(request_id uuid,target academic.enrollment_request_status,command_name academic.enrollment_command_type,permission text,reason academic.enrollment_eligibility_reason,operation_key text,correlation uuid)
returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; request academic.enrollment_requests%rowtype; event academic.student_academic_event_type;
begin actor:=academic.require_student_enrollment_permission(permission); prior:=academic.begin_enrollment_command(actor,command_name,operation_key,jsonb_build_object('request',request_id,'target',target,'reason',reason)); if prior is not null then return query select prior,target::text; return; end if; select * into request from academic.enrollment_requests where id=request_id for update; if request.id is null then raise exception 'ENROLLMENT_REQUEST_NOT_FOUND'; end if; if not academic.valid_enrollment_request_transition(request.status,target) then raise exception 'ENROLLMENT_REQUEST_INVALID_STATE'; end if;
 if target='APPROVED' and request.eligibility_status not in ('ELIGIBLE','ELIGIBLE_WITH_CONDITIONS') then raise exception 'ACADEMIC_RESULT_PENDING'; end if; if target='CANCELLED' and request.status='APPROVED' and exists(select 1 from academic.period_enrollments where enrollment_request_id=request_id) then raise exception 'ENROLLMENT_REQUEST_INVALID_STATE'; end if;
 event:=case target when 'SUBMITTED' then 'ENROLLMENT_REQUEST_SUBMITTED' when 'UNDER_REVIEW' then 'ENROLLMENT_REQUEST_REVIEW_STARTED' when 'APPROVED' then 'ENROLLMENT_REQUEST_APPROVED' when 'REJECTED' then 'ENROLLMENT_REQUEST_REJECTED' when 'CANCELLED' then 'ENROLLMENT_REQUEST_CANCELLED' when 'EXPIRED' then 'ENROLLMENT_REQUEST_EXPIRED' end;
 perform set_config('academic.student_controlled_mutation','on',true); update academic.enrollment_requests set status=target,eligibility_reason_code=coalesce(reason,eligibility_reason_code),reviewed_by_account_id=case when target='UNDER_REVIEW' then actor else reviewed_by_account_id end,approved_by_account_id=case when target='APPROVED' then actor else approved_by_account_id end,rejected_by_account_id=case when target='REJECTED' then actor else rejected_by_account_id end,reviewed_at=case when target='UNDER_REVIEW' then statement_timestamp() else reviewed_at end,approved_at=case when target='APPROVED' then statement_timestamp() else approved_at end,rejected_at=case when target='REJECTED' then statement_timestamp() else rejected_at end,cancelled_at=case when target='CANCELLED' then statement_timestamp() else cancelled_at end,updated_at=statement_timestamp() where id=request_id; perform set_config('academic.student_controlled_mutation','off',true);
 perform academic.append_student_event(request.student_record_id,'ENROLLMENT_REQUEST',request_id,event,actor,request.status::text,target::text,'ACADEMIC_DECISION',operation_key,correlation); perform academic.complete_enrollment_command(actor,command_name,operation_key,'ENROLLMENT_REQUEST',request_id); return query select request_id,target::text; end$$;
create function academic.submit_enrollment_request(request_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_enrollment_request_status(request_id,'SUBMITTED','SUBMIT_ENROLLMENT_REQUEST','academic.enrollment_requests.manage',null,operation_key,correlation)$$;
create function academic.begin_enrollment_review(request_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_enrollment_request_status(request_id,'UNDER_REVIEW','BEGIN_ENROLLMENT_REVIEW','academic.enrollment_requests.manage',null,operation_key,correlation)$$;
create function academic.approve_enrollment_request(request_id uuid,reason academic.enrollment_eligibility_reason,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_enrollment_request_status(request_id,'APPROVED','APPROVE_ENROLLMENT_REQUEST','academic.enrollment_requests.manage',reason,operation_key,correlation)$$;
create function academic.reject_enrollment_request(request_id uuid,reason academic.enrollment_eligibility_reason,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_enrollment_request_status(request_id,'REJECTED','REJECT_ENROLLMENT_REQUEST','academic.enrollment_requests.manage',reason,operation_key,correlation)$$;
create function academic.cancel_enrollment_request(request_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_enrollment_request_status(request_id,'CANCELLED','CANCEL_ENROLLMENT_REQUEST','academic.enrollment_requests.manage',null,operation_key,correlation)$$;
create function academic.expire_enrollment_request(request_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_enrollment_request_status(request_id,'EXPIRED','EXPIRE_ENROLLMENT_REQUEST','academic.enrollment_requests.manage',null,operation_key,correlation)$$;

create function academic.validate_group_curriculum_coverage(group_id uuid) returns table(complete boolean,expected_count integer,offered_count integer) language sql stable security definer set search_path='' as $$
 with g as(select * from academic.groups where id=group_id), expected as(select c.id,(select count(*) from academic.subject_units u where u.curriculum_subject_id=c.id) unit_count from academic.curriculum_subjects c join academic.plan_semesters s on s.id=c.plan_semester_id join g on g.study_plan_id=c.study_plan_id and g.semester_number=s.semester_number where c.status='ACTIVE' and c.is_mandatory and c.training_area_id is not distinct from case when g.semester_number>=5 then g.training_area_id else null end), offered as(select o.curriculum_subject_id from academic.academic_offerings o join g on g.id=o.group_id where o.status='ACTIVE') select not exists(select 1 from expected where unit_count<>3) and not exists((select id from expected except select curriculum_subject_id from offered) union all (select curriculum_subject_id from offered except select id from expected)),(select count(*)::integer from expected),(select count(*)::integer from offered)
$$;

create function academic.create_period_enrollment(request_id uuid,enrollment_code text,operation_key text,correlation uuid default null)
returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; created uuid; request academic.enrollment_requests%rowtype; record academic.student_records%rowtype; g academic.groups%rowtype; p academic.academic_periods%rowtype; occupied integer;
begin actor:=academic.require_student_enrollment_permission('academic.enrollments.manage'); prior:=academic.begin_enrollment_command(actor,'CREATE_PERIOD_ENROLLMENT',operation_key,jsonb_build_object('request',request_id,'code',enrollment_code)); if prior is not null then return query select prior,'PLANNED'; return; end if;
 select * into request from academic.enrollment_requests where id=request_id for update; if request.id is null or request.status<>'APPROVED' or request.requested_group_id is null then raise exception 'ENROLLMENT_REQUEST_INVALID_STATE'; end if; select * into record from academic.student_records where id=request.student_record_id for update; select * into p from academic.academic_periods where id=request.academic_period_id for update; select * into g from academic.groups where id=request.requested_group_id for update;
 if record.status<>'ACTIVE' then raise exception 'STUDENT_RECORD_NOT_ACTIVE'; end if; if p.status not in ('PLANNED','ACTIVE') then raise exception 'PERIOD_NOT_AVAILABLE'; end if; if g.status not in ('OPEN','ACTIVE') or g.academic_period_id<>p.id or g.study_plan_id<>record.study_plan_id or g.semester_number<>request.requested_semester_number or g.training_area_id is distinct from request.requested_training_area_id then raise exception 'GROUP_NOT_COMPATIBLE'; end if;
 if g.capacity is not null then select count(*) into occupied from academic.period_enrollments e where e.group_id=g.id and e.status in ('PLANNED','ACTIVE','TEMPORARILY_SUSPENDED'); if occupied>=g.capacity then raise exception 'GROUP_CAPACITY_REACHED'; end if; end if;
 insert into academic.period_enrollments(student_record_id,enrollment_request_id,academic_period_id,study_plan_id,semester_number,training_area_id,group_id,enrollment_number,enrolled_by_account_id) values(record.id,request.id,p.id,record.study_plan_id,request.requested_semester_number,request.requested_training_area_id,g.id,enrollment_code,actor) returning id into created;
 perform set_config('academic.student_controlled_mutation','on',true); update academic.enrollment_requests set status='ENROLLED',updated_at=statement_timestamp() where id=request.id; update academic.student_records set first_enrollment_period_id=coalesce(first_enrollment_period_id,p.id),last_enrollment_period_id=p.id,updated_at=statement_timestamp() where id=record.id; perform set_config('academic.student_controlled_mutation','off',true);
 perform academic.append_student_event(record.id,'PERIOD_ENROLLMENT',created,'PERIOD_ENROLLMENT_CREATED',actor,null,'PLANNED','INITIAL_ENROLLMENT',operation_key,correlation); perform academic.complete_enrollment_command(actor,'CREATE_PERIOD_ENROLLMENT',operation_key,'PERIOD_ENROLLMENT',created); return query select created,'PLANNED'; end$$;

create function academic.assign_student_group(enrollment_id uuid,group_id uuid,kind academic.student_group_assignment_type,reason academic.student_history_reason,operation_key text,correlation uuid default null)
returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; created uuid; e academic.period_enrollments%rowtype; g academic.groups%rowtype;
begin actor:=academic.require_student_enrollment_permission('academic.group_assignments.manage'); prior:=academic.begin_enrollment_command(actor,'ASSIGN_STUDENT_GROUP',operation_key,jsonb_build_object('enrollment',enrollment_id,'group',group_id,'kind',kind,'reason',reason)); if prior is not null then return query select prior,'ACTIVE'; return; end if; select * into e from academic.period_enrollments where id=enrollment_id for update; select * into g from academic.groups where id=group_id for update; if e.id is null or g.id is null or e.academic_period_id<>g.academic_period_id or e.study_plan_id<>g.study_plan_id or e.semester_number<>g.semester_number or e.training_area_id is distinct from g.training_area_id then raise exception 'GROUP_NOT_COMPATIBLE'; end if;
 insert into academic.student_group_assignments(period_enrollment_id,group_id,assignment_type,assigned_by_account_id,reason_code,idempotency_key) values(enrollment_id,group_id,kind,actor,reason,operation_key) returning id into created; perform academic.append_student_event(e.student_record_id,'GROUP_ASSIGNMENT',created,'GROUP_ASSIGNED',actor,null,'ACTIVE',reason,operation_key,correlation); perform academic.complete_enrollment_command(actor,'ASSIGN_STUDENT_GROUP',operation_key,'GROUP_ASSIGNMENT',created); return query select created,'ACTIVE'; end$$;

create function academic.populate_student_group_offerings(enrollment_id uuid,actor uuid) returns integer language plpgsql security definer set search_path='' as $$declare e academic.period_enrollments%rowtype; coverage record; inserted integer;
begin select * into e from academic.period_enrollments where id=enrollment_id for update; select * into coverage from academic.validate_group_curriculum_coverage(e.group_id); if not coverage.complete then raise exception 'CURRICULUM_COVERAGE_INCOMPLETE'; end if; insert into academic.student_offering_enrollments(period_enrollment_id,academic_offering_id,enrolled_by_account_id) select e.id,o.id,actor from academic.academic_offerings o where o.group_id=e.group_id and o.status='ACTIVE' on conflict(period_enrollment_id,academic_offering_id) do nothing; get diagnostics inserted=row_count; return inserted; end$$;
create function academic.enroll_student_in_group_offerings(enrollment_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; e academic.period_enrollments%rowtype; inserted integer;
begin actor:=academic.require_student_enrollment_permission('academic.enrollments.manage'); prior:=academic.begin_enrollment_command(actor,'ENROLL_STUDENT_IN_GROUP_OFFERINGS',operation_key,jsonb_build_object('enrollment',enrollment_id)); if prior is not null then return query select prior,'ACTIVE'; return; end if; select * into e from academic.period_enrollments where id=enrollment_id for update; if e.id is null then raise exception 'ENROLLMENT_ALREADY_EXISTS'; end if; inserted:=academic.populate_student_group_offerings(enrollment_id,actor); if inserted=0 and not exists(select 1 from academic.student_offering_enrollments where period_enrollment_id=enrollment_id) then raise exception 'CURRICULUM_COVERAGE_INCOMPLETE'; end if; perform academic.append_student_event(e.student_record_id,'PERIOD_ENROLLMENT',e.id,'OFFERING_ENROLLMENTS_CREATED',actor,null,'ACTIVE','INITIAL_ENROLLMENT',operation_key,correlation); perform academic.complete_enrollment_command(actor,'ENROLL_STUDENT_IN_GROUP_OFFERINGS',operation_key,'PERIOD_ENROLLMENT',e.id); return query select e.id,'ACTIVE'; end$$;

create function academic.change_period_enrollment_status(enrollment_id uuid,target academic.period_enrollment_status,command_name academic.enrollment_command_type,operation_key text,correlation uuid)
returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; e academic.period_enrollments%rowtype; record academic.student_records%rowtype; record_id uuid; p_status academic.structure_status; g_status academic.group_status; event academic.student_academic_event_type;
begin actor:=academic.require_student_enrollment_permission('academic.enrollments.manage'); prior:=academic.begin_enrollment_command(actor,command_name,operation_key,jsonb_build_object('enrollment',enrollment_id,'target',target)); if prior is not null then return query select prior,target::text; return; end if; select pe.student_record_id into record_id from academic.period_enrollments pe where pe.id=enrollment_id; if record_id is null then raise exception 'INVALID_STATE_TRANSITION'; end if; select * into record from academic.student_records sr where sr.id=record_id for update; select * into e from academic.period_enrollments pe where pe.id=enrollment_id for update; if e.id is null or not academic.valid_period_enrollment_transition(e.status,target) then raise exception 'INVALID_STATE_TRANSITION'; end if; select p.status into p_status from academic.academic_periods p where p.id=e.academic_period_id for update; select g.status into g_status from academic.groups g where g.id=e.group_id for update;
 if target='ACTIVE' then if record.status<>'ACTIVE' then raise exception 'STUDENT_RECORD_NOT_ACTIVE'; end if; if p_status<>'ACTIVE' then raise exception 'PERIOD_CLOSING'; end if; if g_status<>'ACTIVE' then raise exception 'GROUP_NOT_AVAILABLE'; end if; if not exists(select 1 from academic.student_group_assignments a where a.period_enrollment_id=e.id and a.group_id=e.group_id and a.status='ACTIVE') then raise exception 'GROUP_ASSIGNMENT_CONFLICT'; end if; perform academic.populate_student_group_offerings(e.id,actor); end if;
 event:=case target when 'ACTIVE' then 'PERIOD_ENROLLMENT_ACTIVATED' when 'COMPLETED' then 'PERIOD_ENROLLMENT_COMPLETED' when 'CANCELLED' then 'PERIOD_ENROLLMENT_CANCELLED' when 'WITHDRAWN' then 'PERIOD_ENROLLMENT_WITHDRAWN' end;
 perform set_config('academic.student_controlled_mutation','on',true); update academic.period_enrollments set status=target,cancelled_by_account_id=case when target='CANCELLED' then actor else cancelled_by_account_id end,completed_by_account_id=case when target='COMPLETED' then actor else completed_by_account_id end,cancelled_at=case when target='CANCELLED' then statement_timestamp() else cancelled_at end,completed_at=case when target='COMPLETED' then statement_timestamp() else completed_at end,updated_at=statement_timestamp() where id=e.id; if target in ('COMPLETED','CANCELLED','WITHDRAWN') then update academic.student_offering_enrollments soe set status=case when target='COMPLETED' then 'COMPLETED'::academic.student_offering_enrollment_status else 'CANCELLED'::academic.student_offering_enrollment_status end,completed_at=case when target='COMPLETED' then statement_timestamp() else soe.completed_at end,cancelled_at=case when target<>'COMPLETED' then statement_timestamp() else soe.cancelled_at end,updated_at=statement_timestamp() where soe.period_enrollment_id=e.id and soe.status='ACTIVE'; end if; perform set_config('academic.student_controlled_mutation','off',true);
 perform academic.append_student_event(e.student_record_id,'PERIOD_ENROLLMENT',e.id,event,actor,e.status::text,target::text,'ACADEMIC_DECISION',operation_key,correlation); perform academic.complete_enrollment_command(actor,command_name,operation_key,'PERIOD_ENROLLMENT',e.id); return query select e.id,target::text; end$$;
create function academic.activate_period_enrollment(enrollment_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_period_enrollment_status(enrollment_id,'ACTIVE','ACTIVATE_PERIOD_ENROLLMENT',operation_key,correlation)$$;
create function academic.complete_period_enrollment(enrollment_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_period_enrollment_status(enrollment_id,'COMPLETED','COMPLETE_PERIOD_ENROLLMENT',operation_key,correlation)$$;
create function academic.cancel_period_enrollment(enrollment_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_period_enrollment_status(enrollment_id,'CANCELLED','CANCEL_PERIOD_ENROLLMENT',operation_key,correlation)$$;
create function academic.withdraw_period_enrollment(enrollment_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_period_enrollment_status(enrollment_id,'WITHDRAWN','WITHDRAW_PERIOD_ENROLLMENT',operation_key,correlation)$$;

create function academic.end_student_group_assignment(assignment_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; a academic.student_group_assignments%rowtype; record_id uuid;
begin actor:=academic.require_student_enrollment_permission('academic.group_assignments.manage'); prior:=academic.begin_enrollment_command(actor,'END_STUDENT_GROUP_ASSIGNMENT',operation_key,jsonb_build_object('assignment',assignment_id)); if prior is not null then return query select prior,'ENDED'; return; end if; select * into a from academic.student_group_assignments where id=assignment_id for update; if a.id is null or a.status<>'ACTIVE' then raise exception 'GROUP_ASSIGNMENT_CONFLICT'; end if; select student_record_id into record_id from academic.period_enrollments where id=a.period_enrollment_id; perform set_config('academic.student_controlled_mutation','on',true); update academic.student_group_assignments set status='ENDED',valid_to=clock_timestamp(),ended_at=clock_timestamp(),ended_by_account_id=actor where id=a.id; perform set_config('academic.student_controlled_mutation','off',true); perform academic.append_student_event(record_id,'GROUP_ASSIGNMENT',a.id,'GROUP_ASSIGNMENT_ENDED',actor,'ACTIVE','ENDED','CORRECTIVE_ACTION',operation_key,correlation); perform academic.complete_enrollment_command(actor,'END_STUDENT_GROUP_ASSIGNMENT',operation_key,'GROUP_ASSIGNMENT',a.id); return query select a.id,'ENDED'; end$$;

create function academic.change_student_group(enrollment_id uuid,new_group_id uuid,kind academic.student_group_assignment_type,reason academic.student_history_reason,operation_key text,correlation uuid default null)
returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; e academic.period_enrollments%rowtype; g academic.groups%rowtype; current academic.student_group_assignments%rowtype; created uuid; occupied integer; p_status academic.structure_status;
begin actor:=academic.require_student_enrollment_permission('academic.group_assignments.manage'); prior:=academic.begin_enrollment_command(actor,'CHANGE_STUDENT_GROUP',operation_key,jsonb_build_object('enrollment',enrollment_id,'group',new_group_id,'kind',kind,'reason',reason)); if prior is not null then return query select prior,'ACTIVE'; return; end if;
 select * into e from academic.period_enrollments where id=enrollment_id for update; select p.status into p_status from academic.academic_periods p where p.id=e.academic_period_id for update; select * into g from academic.groups where id=new_group_id for update; select * into current from academic.student_group_assignments a where a.period_enrollment_id=e.id and a.status='ACTIVE' for update;
 if e.id is null or p_status in ('CLOSING','CLOSED','CANCELLED') or g.id is null or g.status not in ('OPEN','ACTIVE') or e.academic_period_id<>g.academic_period_id or e.study_plan_id<>g.study_plan_id or e.semester_number<>g.semester_number or e.training_area_id is distinct from g.training_area_id then raise exception 'GROUP_NOT_COMPATIBLE'; end if;
 if g.capacity is not null then select count(*) into occupied from academic.period_enrollments x where x.group_id=g.id and x.id<>e.id and x.status in ('PLANNED','ACTIVE','TEMPORARILY_SUSPENDED'); if occupied>=g.capacity then raise exception 'GROUP_CAPACITY_REACHED'; end if; end if;
 perform set_config('academic.student_controlled_mutation','on',true); update academic.student_group_assignments set status='ENDED',valid_to=clock_timestamp(),ended_at=clock_timestamp(),ended_by_account_id=actor where id=current.id; update academic.period_enrollments set group_id=g.id,updated_at=clock_timestamp() where id=e.id; update academic.student_offering_enrollments soe set status='CANCELLED',cancelled_at=clock_timestamp(),updated_at=clock_timestamp() where soe.period_enrollment_id=e.id and soe.status='ACTIVE'; insert into academic.student_group_assignments(period_enrollment_id,group_id,assignment_type,assigned_by_account_id,reason_code,idempotency_key,valid_from) values(e.id,g.id,kind,actor,reason,operation_key,clock_timestamp()) returning id into created; perform set_config('academic.student_controlled_mutation','off',true);
 if e.status='ACTIVE' then perform academic.populate_student_group_offerings(e.id,actor); end if; perform academic.append_student_event(e.student_record_id,'GROUP_ASSIGNMENT',created,'GROUP_CHANGED',actor,current.group_id::text,g.id::text,reason,operation_key,correlation); perform academic.complete_enrollment_command(actor,'CHANGE_STUDENT_GROUP',operation_key,'GROUP_ASSIGNMENT',created); return query select created,'ACTIVE'; end$$;

create function academic.create_progress_decision(record_id uuid,source_enrollment_id uuid,source_period_id uuid,kind academic.progress_decision_type,resulting_semester smallint,resulting_area uuid,reason academic.enrollment_eligibility_reason,effective_period uuid,operation_key text,correlation uuid default null)
returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; created uuid; record academic.student_records%rowtype;
begin actor:=academic.require_student_enrollment_permission('academic.progress.manage'); prior:=academic.begin_enrollment_command(actor,'CREATE_PROGRESS_DECISION',operation_key,jsonb_build_object('record',record_id,'source_enrollment',source_enrollment_id,'source_period',source_period_id,'kind',kind,'semester',resulting_semester,'area',resulting_area,'reason',reason,'effective',effective_period)); if prior is not null then return query select prior,'DRAFT'; return; end if; select * into record from academic.student_records where id=record_id for update; if record.id is null then raise exception 'STUDENT_RECORD_NOT_FOUND'; end if;
 if kind='ADVANCE' and (record.current_semester_number>=6 or resulting_semester<>record.current_semester_number+1) then raise exception 'SEMESTER_ADVANCE_NOT_ALLOWED'; end if; if kind='REPEAT' and resulting_semester<>record.current_semester_number then raise exception 'SEMESTER_REPEAT_REQUIRED'; end if; if kind='COMPLETE_STUDIES' and record.current_semester_number<>6 then raise exception 'SEMESTER_ADVANCE_NOT_ALLOWED'; end if; if (resulting_semester<5 and resulting_area is not null) or (resulting_semester>=5 and resulting_area is null) then raise exception 'TRAINING_AREA_NOT_ALLOWED'; end if;
 insert into academic.academic_progress_decisions(student_record_id,source_period_enrollment_id,source_academic_period_id,decision_type,resulting_semester_number,resulting_training_area_id,reason_code,decided_by_account_id,idempotency_key,request_fingerprint,effective_from_period_id) values(record_id,source_enrollment_id,source_period_id,kind,resulting_semester,resulting_area,reason,actor,operation_key,academic.academic_request_fingerprint(jsonb_build_object('record',record_id,'source_enrollment',source_enrollment_id,'source_period',source_period_id,'kind',kind,'semester',resulting_semester,'area',resulting_area,'reason',reason,'effective',effective_period)),effective_period) returning id into created;
 perform academic.append_student_event(record_id,'PROGRESS_DECISION',created,'PROGRESS_DECISION_CREATED',actor,null,'DRAFT','ACADEMIC_DECISION',operation_key,correlation); perform academic.complete_enrollment_command(actor,'CREATE_PROGRESS_DECISION',operation_key,'PROGRESS_DECISION',created); return query select created,'DRAFT'; end$$;

create function academic.confirm_progress_decision(decision_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; d academic.academic_progress_decisions%rowtype; record academic.student_records%rowtype; new_status academic.student_record_status; event academic.student_academic_event_type;
begin actor:=academic.require_student_enrollment_permission('academic.progress.manage'); prior:=academic.begin_enrollment_command(actor,'CONFIRM_PROGRESS_DECISION',operation_key,jsonb_build_object('decision',decision_id)); if prior is not null then return query select prior,'CONFIRMED'; return; end if; select * into d from academic.academic_progress_decisions where id=decision_id for update; select * into record from academic.student_records where id=d.student_record_id for update; if d.id is null or d.decision_status<>'DRAFT' then raise exception 'PROGRESS_DECISION_CONFLICT'; end if;
 new_status:=case d.decision_type when 'HOLD' then 'ACADEMICALLY_BLOCKED' when 'TEMPORARY_WITHDRAWAL' then 'TEMPORARILY_WITHDRAWN' when 'PERMANENT_WITHDRAWAL' then 'PERMANENTLY_WITHDRAWN' when 'COMPLETE_STUDIES' then 'COMPLETED' else record.status end; event:=case d.decision_type when 'ADVANCE' then 'SEMESTER_ADVANCED' when 'REPEAT' then 'SEMESTER_REPEAT_REQUIRED' when 'HOLD' then 'ACADEMIC_HOLD_APPLIED' when 'TEMPORARY_WITHDRAWAL' then 'TEMPORARY_WITHDRAWAL_APPLIED' when 'PERMANENT_WITHDRAWAL' then 'PERMANENT_WITHDRAWAL_APPLIED' when 'COMPLETE_STUDIES' then 'STUDIES_COMPLETED' end;
 perform set_config('academic.student_controlled_mutation','on',true); update academic.academic_progress_decisions set decision_status='CONFIRMED',approved_by_account_id=actor where id=d.id; update academic.student_records set status=new_status,current_semester_number=d.resulting_semester_number,current_training_area_id=d.resulting_training_area_id,withdrawn_at=case when new_status in ('TEMPORARILY_WITHDRAWN','PERMANENTLY_WITHDRAWN') then statement_timestamp() else withdrawn_at end,updated_at=statement_timestamp() where id=record.id; perform set_config('academic.student_controlled_mutation','off',true);
 if new_status<>record.status then insert into academic.student_status_history(student_record_id,previous_status,resulting_status,reason_code,actor_account_id,source_entity_type,source_entity_id) values(record.id,record.status,new_status,(case d.decision_type when 'HOLD' then 'ADMINISTRATIVE_HOLD' when 'TEMPORARY_WITHDRAWAL' then 'TEMPORARY_WITHDRAWAL' when 'PERMANENT_WITHDRAWAL' then 'PERMANENT_WITHDRAWAL' when 'COMPLETE_STUDIES' then 'STUDIES_COMPLETED' else 'ACADEMIC_DECISION' end)::academic.student_history_reason,actor,'PROGRESS_DECISION',d.id); end if;
 perform academic.append_student_event(record.id,'PROGRESS_DECISION',d.id,event,actor,'DRAFT','CONFIRMED','ACADEMIC_DECISION',operation_key,correlation); perform academic.complete_enrollment_command(actor,'CONFIRM_PROGRESS_DECISION',operation_key,'PROGRESS_DECISION',d.id); return query select d.id,'CONFIRMED'; end$$;

create function academic.reverse_progress_decision(decision_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; d academic.academic_progress_decisions%rowtype;
begin actor:=academic.require_student_enrollment_permission('academic.progress.manage'); prior:=academic.begin_enrollment_command(actor,'REVERSE_PROGRESS_DECISION',operation_key,jsonb_build_object('decision',decision_id)); if prior is not null then return query select prior,'REVERSED'; return; end if; select * into d from academic.academic_progress_decisions where id=decision_id for update; if d.id is null or d.decision_status<>'CONFIRMED' then raise exception 'PROGRESS_DECISION_CONFLICT'; end if; perform set_config('academic.student_controlled_mutation','on',true); update academic.academic_progress_decisions set decision_status='REVERSED',reversed_at=statement_timestamp() where id=d.id; perform set_config('academic.student_controlled_mutation','off',true); perform academic.append_student_event(d.student_record_id,'PROGRESS_DECISION',d.id,'PROGRESS_DECISION_REVERSED',actor,'CONFIRMED','REVERSED','CORRECTIVE_ACTION',operation_key,correlation); perform academic.complete_enrollment_command(actor,'REVERSE_PROGRESS_DECISION',operation_key,'PROGRESS_DECISION',d.id); return query select d.id,'REVERSED'; end$$;

create function academic.change_student_record_status(record_id uuid,target academic.student_record_status,command_name academic.enrollment_command_type,permission text,reason academic.student_history_reason,event academic.student_academic_event_type,operation_key text,correlation uuid)
returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; record academic.student_records%rowtype;
begin actor:=academic.require_student_enrollment_permission(permission); prior:=academic.begin_enrollment_command(actor,command_name,operation_key,jsonb_build_object('record',record_id,'target',target,'reason',reason)); if prior is not null then return query select prior,target::text; return; end if; select * into record from academic.student_records where id=record_id for update; if record.id is null or not academic.valid_student_record_transition(record.status,target) then raise exception 'INVALID_STATE_TRANSITION'; end if; perform set_config('academic.student_controlled_mutation','on',true); update academic.student_records set status=target,withdrawn_at=case when target in ('TEMPORARILY_WITHDRAWN','PERMANENTLY_WITHDRAWN') then statement_timestamp() when target='ACTIVE' then null else withdrawn_at end,updated_at=statement_timestamp() where id=record.id; perform set_config('academic.student_controlled_mutation','off',true); insert into academic.student_status_history(student_record_id,previous_status,resulting_status,reason_code,actor_account_id,source_entity_type,source_entity_id) values(record.id,record.status,target,reason,actor,'STUDENT_RECORD',record.id); perform academic.append_student_event(record.id,'STUDENT_RECORD',record.id,event,actor,record.status::text,target::text,reason,operation_key,correlation); perform academic.complete_enrollment_command(actor,command_name,operation_key,'STUDENT_RECORD',record.id); return query select record.id,target::text; end$$;
create function academic.apply_temporary_withdrawal(record_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare record academic.student_records%rowtype; begin
 perform academic.require_student_enrollment_permission('academic.students.manage'); select * into record from academic.student_records sr where sr.id=$1 for update;
 if record.status<>'TEMPORARILY_WITHDRAWN' and exists(select 1 from academic.period_enrollments pe where pe.student_record_id=$1 and pe.status='ACTIVE') then raise exception 'ACTIVE_ENROLLMENT_EXISTS'; end if;
 return query select * from academic.change_student_record_status(record_id,'TEMPORARILY_WITHDRAWN','APPLY_TEMPORARY_WITHDRAWAL','academic.students.manage','TEMPORARY_WITHDRAWAL','TEMPORARY_WITHDRAWAL_APPLIED',operation_key,correlation);
end$$;
create function academic.reactivate_student_record(record_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_student_record_status(record_id,'ACTIVE','REACTIVATE_STUDENT_RECORD','academic.students.manage','REACTIVATION','STUDENT_REACTIVATED',operation_key,correlation)$$;
create function academic.apply_academic_hold(record_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_student_record_status(record_id,'ACADEMICALLY_BLOCKED','APPLY_ACADEMIC_HOLD','academic.progress.manage','ADMINISTRATIVE_HOLD','ACADEMIC_HOLD_APPLIED',operation_key,correlation)$$;
create function academic.release_academic_hold(record_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_student_record_status(record_id,'ACTIVE','RELEASE_ACADEMIC_HOLD','academic.progress.manage','HOLD_RELEASED','ACADEMIC_HOLD_RELEASED',operation_key,correlation)$$;
create function academic.apply_permanent_withdrawal(record_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_student_record_status(record_id,'PERMANENTLY_WITHDRAWN','APPLY_PERMANENT_WITHDRAWAL','academic.withdrawals.manage','PERMANENT_WITHDRAWAL','PERMANENT_WITHDRAWAL_APPLIED',operation_key,correlation)$$;
create function academic.complete_student_studies(record_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare semester smallint; begin select current_semester_number into semester from academic.student_records where id=record_id; if semester<>6 then raise exception 'SEMESTER_ADVANCE_NOT_ALLOWED'; end if; return query select * from academic.change_student_record_status(record_id,'COMPLETED','COMPLETE_STUDENT_STUDIES','academic.progress.manage','STUDIES_COMPLETED','STUDIES_COMPLETED',operation_key,correlation); end$$;

do $$declare f record; begin for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='academic' loop execute format('alter function %s owner to postgres',f.signature); execute format('revoke execute on function %s from public,anon,authenticated',f.signature); end loop; end$$;
revoke all on all tables in schema academic from public,anon,authenticated;
alter default privileges in schema academic revoke all on tables from public,anon,authenticated;
alter default privileges in schema academic revoke execute on functions from public,anon,authenticated;

commit;
